@import url("https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Fraunces:opsz,wght@9..144,600;9..144,700&display=swap");

:root {
  color-scheme: light;
  --ink-950: #172019;
  --ink-800: #2e3b32;
  --ink-600: #5c695f;
  --ink-400: #89938b;
  --paper: #f7f4ec;
  --paper-deep: #eee8da;
  --surface: #fffdf7;
  --surface-raised: #ffffff;
  --line: #ded8ca;
  --line-strong: #c8c0af;
  --leaf-700: #315f45;
  --leaf-600: #3f7656;
  --leaf-500: #57906a;
  --leaf-100: #e1eddf;
  --sun-500: #dda94c;
  --sun-100: #faedcc;
  --danger-700: #9a3b32;
  --danger-100: #f9e4df;
  --shadow-soft: 0 16px 44px rgba(51, 60, 46, 0.09);
  --shadow-small: 0 5px 16px rgba(51, 60, 46, 0.09);
  --radius-small: 0.55rem;
  --radius-medium: 0.9rem;
  --radius-large: 1.35rem;
  --font-body: "DM Sans", system-ui, sans-serif;
  --font-display: "Fraunces", Georgia, serif;
  font-family: var(--font-body);
  font-synthesis: none;
  line-height: 1.5;
  color: var(--ink-950);
  background: var(--paper);
}

* {
  box-sizing: border-box;
}

html {
  min-width: 320px;
  min-height: 100%;
  background: var(--paper);
}

body {
  min-width: 320px;
  min-height: 100vh;
  margin: 0;
  background:
    radial-gradient(circle at 85% 5%, rgba(221, 169, 76, 0.12), transparent 28rem),
    var(--paper);
  color: var(--ink-950);
}

button,
input,
textarea,
select {
  font: inherit;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

a {
  color: var(--leaf-700);
}

:focus-visible {
  outline: 3px solid var(--sun-500);
  outline-offset: 3px;
}

.skip-link {
  position: fixed;
  z-index: 100;
  top: 0.75rem;
  left: 0.75rem;
  padding: 0.65rem 0.9rem;
  border-radius: var(--radius-small);
  background: var(--ink-950);
  color: white;
  transform: translateY(-180%);
